/**
 * Auth + lead_id + payload. Bez treści Telegram — robi Perplexity + Code_Format.
 */
function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}
const item = $input.first().json;
const headers = item.headers || {};
const auth = String(headers.authorization || headers.Authorization || '').trim();
let secret = '';
try { secret = String($env.HITL_WEBHOOK_SECRET || '').trim(); } catch (e) {}
if (!secret || auth !== 'Bearer ' + secret) {
  return [{ json: { unauthorized: true } }];
}
const body = item.body;
if (!body || typeof body !== 'object') {
  return [{ json: { unauthorized: true, bad_body: true } }];
}
const source = String(body.source || 'mail');
const payload_json = body.payload_json != null ? body.payload_json : body;
const ai_json = body.ai_json != null ? body.ai_json : null;
let chatId = '';
try { chatId = String($env.TELEGRAM_OPERATOR_CHAT_ID || '').trim(); } catch (e) {}
if (!chatId) throw new Error('Ustaw TELEGRAM_OPERATOR_CHAT_ID (env)');
const lead_id = uuidv4();
return [{
  json: {
    unauthorized: false,
    lead_id,
    source,
    payload_json,
    ai_json,
    chatId,
    callback_approve: 'ap:' + lead_id,
    callback_reject: 'rj:' + lead_id,
    callback_modify: 'md:' + lead_id,
  },
}];

const prep = $('Code_AuthAndPrepare').first().json;
const item = $input.first().json;
const root = item.body && typeof item.body === 'object' ? item.body : item;
let draft = '';
try {
  const raw = root.choices && root.choices[0] && root.choices[0].message && root.choices[0].message.content;
  draft = typeof raw === 'string' ? raw.trim() : '';
} catch (e) {}
if (!draft) draft = '(Perplexity nie zwrócił treści — ułóż odpowiedź ręcznie po akceptacji.)';
const p = prep.payload_json || {};
const subj = String(p.emailSubject || '(brak tematu)').slice(0, 200);
const bodyRaw = String(p.emailBodyForAi || p.emailBody || '').replace(/\s+/g, ' ').trim();
const bodyPrev = bodyRaw.length > 1200 ? bodyRaw.slice(0, 1200) + '…' : bodyRaw;
const from = String(p.emailFrom || p.client_to_email || '').slice(0, 120);
const phone = String(p.wp_form_phone || '').slice(0, 40);
const name = String(p.wp_form_name || '').slice(0, 80);
const idShort = String(prep.lead_id || '').slice(0, 8);
let telegram_text =
  'ZAPYTANIE (formularz)\n' +
  'Temat: ' + subj + '\n' +
  'Od: ' + from + (name ? ' | ' + name : '') + (phone ? ' | tel. ' + phone : '') + '\n\n' +
  'TRESC:\n' + (bodyPrev || '(brak tresci)') + '\n\n' +
  'PROPOZYCJA ODPOWIEDZI (Perplexity):\n' + draft + '\n\n' +
  'ID (skrot): ' + idShort + '… | Akceptuj / Odrzuc / Modyfikuj — przyciski ponizej.';
if (telegram_text.length > 4090) telegram_text = telegram_text.slice(0, 4087) + '...';
const aiMerged = Object.assign({}, prep.ai_json && typeof prep.ai_json === 'object' ? prep.ai_json : {}, {
  proposed_email_reply: draft,
  hitl_enqueue_version: '2-perplexity-telegram',
});
return [{
  json: {
    lead_id: prep.lead_id,
    source: prep.source,
    payload_json: prep.payload_json,
    ai_json: aiMerged,
    chatId: prep.chatId,
    callback_approve: prep.callback_approve,
    callback_reject: prep.callback_reject,
    callback_modify: prep.callback_modify,
    telegram_text,
  },
}];
